/**
 * "GlyphLessFont" — the tiny TrueType font Tesseract embeds in its own searchable PDFs
 * (pdf.ttf / pdf_ttf.h from https://github.com/tesseract-ocr/tesseract, © Google,
 * Apache License 2.0). One empty glyph, so it never draws anything; used only for the
 * invisible OCR text layer, where each character code maps back to Unicode via ToUnicode.
 */
export const GLYPHLESS_TTF_BASE64 =
  '';

export function glyphlessTtf(): Uint8Array {
  return Uint8Array.from(atob(GLYPHLESS_TTF_BASE64), (c) => c.charCodeAt(0));
}
